CREATE TABLE service_principals(workspace_id uuid NOT NULL,id uuid NOT NULL,owner_user_id uuid NOT NULL,name text NOT NULL,purpose text NOT NULL,role text NOT NULL,scopes jsonb NOT NULL,resource_restrictions jsonb NOT NULL DEFAULT '{}'::jsonb,environment text NOT NULL CHECK(environment IN('test','live')),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','disabled','revoked')),expires_at timestamptz,last_used_at timestamptz,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id));
CREATE TABLE api_credentials(workspace_id uuid NOT NULL,id uuid NOT NULL,principal_id uuid NOT NULL,prefix text NOT NULL,secret_hash text NOT NULL,expires_at timestamptz NOT NULL,overlap_expires_at timestamptz,revoked_at timestamptz,last_used_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(prefix),FOREIGN KEY(workspace_id,principal_id) REFERENCES service_principals(workspace_id,id));
CREATE INDEX api_credentials_lookup_idx ON api_credentials(prefix) WHERE revoked_at IS NULL;
CREATE TABLE oauth_clients(workspace_id uuid NOT NULL,id uuid NOT NULL,owner_user_id uuid NOT NULL,name text NOT NULL,client_identifier text NOT NULL,redirect_uris jsonb NOT NULL,scopes jsonb NOT NULL,state text NOT NULL DEFAULT 'active',secret_hash text NOT NULL,secret_version integer NOT NULL DEFAULT 1,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(client_identifier));
CREATE TABLE outgoing_webhooks(workspace_id uuid NOT NULL,id uuid NOT NULL,owner_user_id uuid NOT NULL,name text NOT NULL,endpoint_url text NOT NULL,event_types jsonb NOT NULL,secret_hash text NOT NULL,secret_version integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'pending_verification' CHECK(state IN('pending_verification','active','disabled')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE outgoing_webhook_deliveries(workspace_id uuid NOT NULL,id uuid NOT NULL,webhook_id uuid NOT NULL,event_id text NOT NULL,event_type text NOT NULL,attempt integer NOT NULL,status text NOT NULL CHECK(status IN('queued','delivered','failed','abandoned')),response_code integer,next_attempt_at timestamptz,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,idempotency_key),FOREIGN KEY(workspace_id,webhook_id) REFERENCES outgoing_webhooks(workspace_id,id));
CREATE INDEX outgoing_webhook_delivery_idx ON outgoing_webhook_deliveries(workspace_id,webhook_id,created_at);
CREATE TABLE public_api_idempotency(workspace_id uuid NOT NULL,credential_id uuid NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,response_status integer,response_body jsonb,expires_at timestamptz NOT NULL,PRIMARY KEY(workspace_id,credential_id,idempotency_key));
CREATE TABLE public_api_rate_buckets(workspace_id uuid NOT NULL,credential_id uuid NOT NULL,route_key text NOT NULL,window_start timestamptz NOT NULL,request_count integer NOT NULL,cost_count integer NOT NULL,PRIMARY KEY(workspace_id,credential_id,route_key,window_start));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['service_principals','api_credentials','oauth_clients','outgoing_webhooks','outgoing_webhook_deliveries','public_api_idempotency','public_api_rate_buckets'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING (knotline_tenant_visible(workspace_id)) WITH CHECK (knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON service_principals,api_credentials,oauth_clients,outgoing_webhooks,outgoing_webhook_deliveries,public_api_idempotency,public_api_rate_buckets FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON service_principals,api_credentials,oauth_clients,outgoing_webhooks,outgoing_webhook_deliveries TO knotline_runtime;
GRANT SELECT,INSERT,UPDATE ON public_api_idempotency,public_api_rate_buckets TO knotline_runtime;
GRANT SELECT ON service_principals,api_credentials,oauth_clients,outgoing_webhooks,outgoing_webhook_deliveries TO knotline_reporting;
